// Verifies package-lock.json against package.json (static, offline): lockfile exists, root entry matches name/version/devDependencies, Playwright resolves to the pinned version with an integrity hash from the npm registry.
// Exit 0 = consistent; 1 = inconsistent; 3 = BLOCKED (no lock in the package — it can only be generated by npm with network access: sh scripts/generate_lock.sh). It never creates or edits a lock.
const fs = require('fs'), path = require('path'); const root = path.join(__dirname, '..');
const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8')); const lp = path.join(root, 'package-lock.json');
if (!fs.existsSync(lp)) { console.log('BLOCKED: package-lock.json is absent. Generate it with npm (needs network): sh scripts/generate_lock.sh — never by hand.'); process.exit(3); }
const lock = JSON.parse(fs.readFileSync(lp, 'utf8')); const bad = []; const r = (lock.packages || {})[''] || {};
if (![2, 3].includes(lock.lockfileVersion)) bad.push('lockfileVersion ' + lock.lockfileVersion + ' (expected 2 or 3)');
if (lock.name !== pkg.name || lock.version !== pkg.version) bad.push('lock name/version ' + lock.name + '@' + lock.version + ' differs from package.json ' + pkg.name + '@' + pkg.version);
if (JSON.stringify(r.devDependencies || {}) !== JSON.stringify(pkg.devDependencies || {})) bad.push('root devDependencies in the lock differ from package.json');
if (JSON.stringify(r.dependencies || {}) !== JSON.stringify(pkg.dependencies || {})) bad.push('root dependencies in the lock differ from package.json');
['playwright', 'playwright-core'].forEach(n => { const e = (lock.packages || {})['node_modules/' + n]; const want = pkg.devDependencies.playwright;
  if (!e) bad.push(n + ' missing from the lock'); else { if (e.version !== want) bad.push(n + ' resolves to ' + e.version + ', package.json pins ' + want); if (!/^sha(512|256)-/.test(e.integrity || '')) bad.push(n + ' has no integrity hash'); if (!/^https:\/\/registry\.npmjs\.org\//.test(e.resolved || '')) bad.push(n + ' not resolved from registry.npmjs.org: ' + e.resolved); } });
Object.entries(lock.packages || {}).forEach(([k, e]) => { if (k && e.resolved && !/^https:\/\/registry\.npmjs\.org\//.test(e.resolved)) bad.push(k + ' resolved outside registry.npmjs.org'); });
if (bad.length) { console.log('LOCK INCONSISTENT:\n - ' + bad.join('\n - ')); process.exit(1); }
console.log('LOCK OK: package-lock.json matches package.json (' + Object.keys(lock.packages).length + ' entries; playwright ' + pkg.devDependencies.playwright + ' with integrity)'); 
